      await f.cli('state', 'next', 'demo', '--continue');
      expect(await f.inspect()).toEqual(original);
      expect(await fs.readFile(path.join(f.base, 'platform-count'), 'utf8')).toBe(
        'actual-' + exitCode + '\n',
      );
    },
  )

